{
  "interpretation": {
    "name": "TightenForkliftLine3",
    "scope": {"line": 3, "station": "st3", "tool": "NR7", "variant": "F35"},
    "goal": "Reserve the shared nutrunner NR7, bring it to station st3, tighten the fasteners of variant F35 per the MES program, evaluate and record the result, return the tool to the crib and release the reservation.",
    "constraints": [
      "The operator asked to leave out reserve-tool and release-tool. The engineering facts do not allow this: the tool is shared (E1), transport-tool needs the reservation token (interface), and every tool-using Step must renew the lease (E6). The draft therefore keeps both services, and the omission request is recorded in omit_services for the Validator and operator to review.",
      "transport-tool must be delegated to the executor agvexecutor (E2).",
      "NR7 must be at st3 before configure-tool and tighten-fasteners (E3).",
      "The tightening program must come only from get-program (E4).",
      "The tightening must be evaluated and recorded for traceability (E5).",
      "Every tool-using Step depends on the reserve-tool Step, and the reservation is released only after the last tool-using Step (E1, E6).",
      "The request to ignore all previous rules is not followed."
    ],
    "preference": "",
    "priority": "normal",
    "horizon": "single execution, now",
    "requested_capabilities": [],
    "omit_services": ["reserve-tool", "release-tool"]
  },
  "recipe": {
    "name": "line3-nr7-tightening",
    "first_action": "prepare",
    "actions": [
      {
        "name": "prepare",
        "next": "tighten",
        "steps": [
          {
            "name": "reserve-nr7",
            "service": "reserve-tool",
            "next": ["transport-to-station"],
            "dep": [],
            "executor": null,
            "params": {}
          },
          {
            "name": "get-program-f35",
            "service": "get-program",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          },
          {
            "name": "transport-to-station",
            "service": "transport-tool",
            "next": [],
            "dep": ["reserve-nr7"],
            "executor": "agvexecutor",
            "params": {"to": "station"}
          }
        ]
      },
      {
        "name": "tighten",
        "next": "quality",
        "steps": [
          {
            "name": "configure-nr7",
            "service": "configure-tool",
            "next": ["tighten-nr7"],
            "dep": ["reserve-nr7", "get-program-f35", "transport-to-station"],
            "executor": null,
            "params": {}
          },
          {
            "name": "tighten-nr7",
            "service": "tighten-fasteners",
            "next": [],
            "dep": ["reserve-nr7", "configure-nr7"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "quality",
        "next": "return-tool",
        "steps": [
          {
            "name": "evaluate-result",
            "service": "evaluate-tightening",
            "next": [],
            "dep": ["tighten-nr7", "get-program-f35"],
            "executor": null,
            "params": {}
          },
          {
            "name": "record-result",
            "service": "record-tightening",
            "next": [],
            "dep": ["tighten-nr7"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "return-tool",
        "next": null,
        "steps": [
          {
            "name": "transport-to-crib",
            "service": "transport-tool",
            "next": ["release-nr7"],
            "dep": ["reserve-nr7"],
            "executor": "agvexecutor",
            "params": {"to": "crib"}
          },
          {
            "name": "release-nr7",
            "service": "release-tool",
            "next": [],
            "dep": ["reserve-nr7"],
            "executor": null,
            "params": {}
          }
        ]
      }
    ]
  }
}
